using System;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Text;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using Demo6.Game;
public static class V10NativeGui {
 delegate bool EnumProc(IntPtr h,IntPtr p);
 [DllImport("user32.dll")]static extern bool EnumWindows(EnumProc cb,IntPtr p);
 [DllImport("user32.dll")]static extern bool EnumChildWindows(IntPtr h,EnumProc cb,IntPtr p);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);
